const sql=require("mssql"),fs=require("fs"),path=require("path"),{getSourceConfig:getSourceConfig}=require("./db.helper");async function inspectTables(){let n;const t=path.resolve(__dirname,"mssql_inspection_report.html");try{const e=getSourceConfig();n=await sql.connect(e);const a=(await n.request().query("\n            SELECT TABLE_NAME \n            FROM INFORMATION_SCHEMA.TABLES \n            WHERE TABLE_TYPE = 'BASE TABLE' \n            AND TABLE_SCHEMA = 'dbo'\n            AND TABLE_NAME LIKE 'hst%'\n            OR TABLE_NAME LIKE 'lab%'\n            ORDER BY TABLE_NAME\n        ")).recordset.map((n=>n.TABLE_NAME));let r=`\n<!DOCTYPE html>\n<html lang="tr">\n<head>\n    <meta charset="UTF-8">\n    <meta name="viewport" content="width=device-width, initial-scale=1.0">\n    <title>MSSQL Veritabanı İnceleme Raporu</title>\n    <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;600&display=swap" rel="stylesheet">\n    <style>\n        :root {\n            --primary: #4f46e5;\n            --bg: #f8fafc;\n            --card-bg: #ffffff;\n            --text: #1e293b;\n            --text-light: #64748b;\n            --border: #e2e8f0;\n        }\n        body {\n            font-family: 'Inter', sans-serif;\n            background-color: var(--bg);\n            color: var(--text);\n            margin: 0;\n            padding: 40px 20px;\n            line-height: 1.5;\n        }\n        .container {\n            max-width: 1200px;\n            margin: 0 auto;\n        }\n        header {\n            margin-bottom: 40px;\n            text-align: center;\n        }\n        h1 {\n            color: var(--primary);\n            font-size: 2.5rem;\n            margin-bottom: 10px;\n        }\n        .stats {\n            display: flex;\n            gap: 20px;\n            justify-content: center;\n            margin-bottom: 30px;\n        }\n        .stat-card {\n            background: var(--card-bg);\n            padding: 15px 25px;\n            border-radius: 12px;\n            box-shadow: 0 4px 6px -1px rgb(0 0 0 / 0.1);\n            border: 1px solid var(--border);\n        }\n        .stat-value {\n            display: block;\n            font-size: 1.5rem;\n            font-weight: 600;\n            color: var(--primary);\n        }\n        .stat-label {\n            font-size: 0.875rem;\n            color: var(--text-light);\n        }\n        .table-section {\n            background: var(--card-bg);\n            border-radius: 16px;\n            border: 1px solid var(--border);\n            margin-bottom: 40px;\n            overflow: hidden;\n            box-shadow: 0 10px 15px -3px rgb(0 0 0 / 0.1);\n        }\n        .table-header {\n            padding: 20px 25px;\n            background: #f1f5f9;\n            border-bottom: 1px solid var(--border);\n            display: flex;\n            justify-content: space-between;\n            align-items: center;\n        }\n        .table-name {\n            font-size: 1.25rem;\n            font-weight: 600;\n            margin: 0;\n            color: #0f172a;\n        }\n        .row-count {\n            background: var(--primary);\n            color: white;\n            padding: 4px 12px;\n            border-radius: 20px;\n            font-size: 0.75rem;\n            font-weight: 600;\n        }\n        .table-container {\n            overflow-x: auto;\n            max-height: 400px;\n        }\n        table {\n            width: 100%;\n            border-collapse: collapse;\n            font-size: 0.875rem;\n        }\n        th {\n            background: #f8fafc;\n            text-align: left;\n            padding: 12px 25px;\n            font-weight: 600;\n            color: var(--text-light);\n            border-bottom: 2px solid var(--border);\n            position: sticky;\n            top: 0;\n            z-index: 10;\n        }\n        td {\n            padding: 12px 25px;\n            border-bottom: 1px solid var(--border);\n            white-space: nowrap;\n            max-width: 300px;\n            overflow: hidden;\n            text-overflow: ellipsis;\n        }\n        tr:hover td {\n            background-color: #f1f5f9;\n        }\n        .empty-state {\n            text-align: center;\n            padding: 20px;\n            color: var(--text-light);\n            font-style: italic;\n        }\n    </style>\n</head>\n<body>\n    <div class="container">\n        <header>\n            <h1>🗄️ Veritabanı İnceleme Raporu</h1>\n            <p>Sunucu: ${e.server} | Veritabanı: ${e.database}</p>\n            <p>Filtrelenmiş tablolar ilk 5 kayıt ile listelenmiştir.</p>\n        </header>\n\n        <div class="stats">\n            <div class="stat-card">\n                <span class="stat-value" id="full-table-count">0</span>\n                <span class="stat-label">Dolu Tablo Sayısı</span>\n            </div>\n        </div>\n\n        <div id="report-content">`,o=0;for(const t of a)try{const e=(await n.request().query(`SELECT COUNT(*) as count FROM [${t}]`)).recordset[0].count;if(e>0){o++,process.stdout.write(`\r✅ Ekleniyor: ${t}`.padEnd(60));const a=(await n.request().query(`SELECT TOP 5 * FROM [${t}]`)).recordset;if(r+=`\n        <section class="table-section">\n            <div class="table-header">\n                <h2 class="table-name">${t}</h2>\n                <span class="row-count">${e.toLocaleString("tr-TR")} Satır</span>\n            </div>\n            <div class="table-container">`,a.length>0){const n=Object.keys(a[0]);r+=`\n                <table>\n                    <thead>\n                        <tr>\n                            ${n.map((n=>`<th>${n}</th>`)).join("")}\n                        </tr>\n                    </thead>\n                    <tbody>\n                        ${a.map((t=>`\n                            <tr>\n                                ${n.map((n=>{let e=t[n];return e instanceof Date&&(e=e.toISOString()),null===e&&(e='<i style="color:#cbd5e1">null</i>'),`<td>${e}</td>`})).join("")}\n                            </tr>\n                        `)).join("")}\n                    </tbody>\n                </table>`}else r+='<div class="empty-state">Veri okunamadı.</div>';r+="\n            </div>\n        </section>"}}catch(n){}r+=`\n        </div>\n    </div>\n    <script>\n        document.getElementById('full-table-count').innerText = '${o}';\n    <\/script>\n</body>\n</html>`,fs.writeFileSync(t,r)}catch(n){}finally{n&&await n.close()}}inspectTables();